function normalizeId(
    id: string | number
): string {
    return typeof id === "string"
        ? id
        : id.toString();
}

type User = {
    id: string;
    email: string;
};

type WithAudit = {
    createdBy: string;
    updatedBy: string;
};

type AuditedUser =
    User & WithAudit;

function print(value: string | number) {
    return value.toUpperCase();
